            $("button").click(function (e) {
                data = new FormData();
                data.append("id", 5);
                data.append("name", "Donald Trump");
                $.ajax("/Home/FromFormExample", {
                    method: "post",
                    processData: false,
                    contentType: false,
                    data: data,
                    success: function (data) {
                        $("#empId").text(data.id);
